#!/usr/bin/env python3
"""Independent English Ae-IV-8 story main-idea rewrite."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / "questions/english"
LESSON = "lesson-english-content-ae-iv-8"
SOURCES = [
    ("https://www.kusjh.kh.edu.tw/upload/files/110%E4%B8%8A%E7%AC%AC1%E6%AC%A1%E6%AE%B5%E8%80%83%E5%9C%8B%E4%B8%AD%E4%B8%80%E5%B9%B4%E7%B4%9A%E8%A9%A6%E9%A1%8C.pdf", "高雄市立鼓山高中國中部七年級公開英語段考", "短文主旨、細節與推論"),
    ("https://www.kcjh.kh.edu.tw/upload/190/104_34764/%E5%9C%8B%E6%98%8C--%E4%B8%89%E5%B9%B4%E7%B4%9A--%E8%8B%B1%E6%96%87%E7%A7%91.pdf", "高雄市立國昌國中公開英語段考", "故事主題、原因與結論"),
    ("https://www.dam.kh.edu.tw/upload/68/101_28414/114-1%E4%B8%83%E5%B9%B4%E7%B4%9A%E7%AC%AC一%E6%AC%A1%E6%AE%B5%E8%80%83%E8%A9%A6%E5%8D%B7%E6%9A%A8%E8%A7%A3%E7%AD%94.pdf", "高雄市立大社國中七年級公開英語段考", "故事段落、主旨與證據"),
]

def refs():
    return [{"url": u, "title": f"{t}；僅研究公開題型與能力方向，未複製原題。", "year": "110-114", "subject": "english", "locator": l, "observedPattern": "公立學校國中英語評量要求整合故事短文的重複線索、事件因果、角色行動與結尾，判斷主旨並排除只涵蓋單一細節的選項；本題採全新文本。", "reuseDecision": "pattern-only", "status": "recorded", "locatorLevel": "paper"} for u, t, l in SOURCES]

DATA = [
    ("Read: **Every Saturday, the neighbors clean the river, sort the trash, and plant flowers along the bank.** What is the main idea?", ["The neighbors work together to care for their river.", "The river is the fastest road in town.", "The neighbors buy flowers for a contest.", "The town has no weekend activities."], "A", "Cleaning, sorting trash and planting flowers all show a shared effort to care for the river.", "整合多個並列動作與共同對象，不被單一花朵細節限制。", ["Identify the repeated subject neighbors.", "List their three actions.", "Find the shared place river.", "Combine them into a main idea.", "Choose the cooperation-and-care statement."]),
    ("A paragraph describes a child practicing the violin daily, making mistakes, asking for feedback, and finally playing a song for the family. What is the best theme?", ["Practice and feedback can lead to improvement.", "Music is impossible to learn.", "Families should never listen to songs.", "Mistakes always end an activity."], "A", "The sequence moves from practice and mistakes to feedback and a successful performance, supporting improvement through effort.", "由事件前後變化歸納主題，而不是只取最後表演。", ["Track the child's repeated practice.", "Notice mistakes and feedback.", "Read the final performance.", "Connect the sequence to improvement.", "Choose the theme supported by all events."]),
    ("A short text says the town added shade trees, benches, and water stations along a walking path. Why did the town likely make these changes?", ["To make walking more comfortable and practical.", "To stop all people from using the path.", "To move the path into a river.", "To remove every tree from the town."], "A", "Shade, benches and water stations all support people who use the path for walking.", "以設施的共同功能推論目的，保留 likely 的合理程度。", ["List the three new features.", "Ask what walkers need on a path.", "Connect shade, rest and water to comfort.", "Choose the likely purpose.", "Avoid claiming the changes guarantee everyone will walk."]),
    ("A story explains that a young cook first wastes food, then measures portions and shares extra meals with neighbors. What change does the story emphasize?", ["The cook learns to reduce waste and help others.", "The cook stops preparing food forever.", "The neighbors refuse every meal.", "Measuring portions makes food disappear."], "A", "The contrast between wasting food and measuring and sharing shows a change toward reducing waste and helping neighbors.", "比較前後行為與結果，找出故事真正的改變。", ["Identify the initial problem wasting food.", "Find the new actions measuring and sharing.", "Compare the effects of the two choices.", "Choose the learning-and-helping change.", "Reject endings not described by the text."]),
    ("A report describes a school garden: students choose seeds, record growth each week, and display their results. What is the report mainly about?", ["How students learn through growing and observing plants.", "How to win a running race.", "Why classrooms need no windows.", "How to repair a bicycle."], "A", "Choosing seeds, recording growth and displaying results all connect gardening with learning and observation.", "找出各段細節共同指向的活動與學習目的。", ["List the students' three actions.", "Identify the common subject plants.", "Connect recording and displaying with learning.", "Choose the main topic.", "Reject options without evidence in the report."]),
    ("A story says a lost child follows a bright park sign, finds a staff member, and returns to her family. Which detail is most important to the resolution?", ["Finding the staff member.", "The color of the child's shoes.", "The weather last week.", "A song on the radio."], "A", "The staff member provides the direct help that leads the child back to her family.", "選出直接解決問題的事件，而非外觀或背景細節。", ["Identify the main problem lost child.", "List the events after following the sign.", "Find the action that provides human help.", "Choose finding the staff member.", "Explain how it connects to the return."]),
    ("A text compares two study spaces and concludes that the quiet room is better for students who need to focus. What supports the conclusion?", ["The quiet room has fewer interruptions.", "The quiet room has a blue wall only.", "The other space sells fruit.", "The students wear different shoes."], "A", "Fewer interruptions directly supports the claim that the room helps students focus.", "將結論與能直接解釋它的證據配對，不選無關外觀。", ["Locate the conclusion about focusing.", "Ask what condition affects concentration.", "Find fewer interruptions.", "Choose the supporting evidence.", "Reject details unrelated to study conditions."]),
    ("A narrative repeats that an old man greets every new neighbor and teaches them the local bus route. What does this repetition suggest?", ["He helps newcomers feel welcome and connected.", "He wants all buses to disappear.", "He dislikes meeting people.", "He never leaves his house."], "A", "Repeated greetings and practical help show a welcoming effort to connect newcomers with the community.", "把重複行動視為人物或主題線索，再概括其共同功能。", ["Notice the action happens with every new neighbor.", "Identify greeting as social welcome.", "Identify teaching the route as practical help.", "Combine them as connection.", "Reject interpretations opposite to repeated interaction."]),
    ("A short text ends: **The team did not win, but they thanked one another and planned to practice together.** What is the best conclusion?", ["The team values cooperation and future improvement.", "The team will never play again.", "Winning was the only thing that mattered.", "The players refuse to speak."], "A", "Thanking one another and planning more practice show cooperation and a goal of improving after the loss.", "用結尾的態度與計畫判斷文章收束意義。", ["Identify the setback did not win.", "Read the response to the setback.", "Notice thanks and a future plan.", "Infer cooperation and improvement.", "Reject conclusions that erase the final actions."]),
    ("A main-idea answer says **The article is about a blue backpack**, but the text describes how students organize a lost-and-found system for many items. Why is the answer weak?", ["It focuses on one example instead of the whole system.", "It includes too many details.", "It identifies the article's exact purpose.", "It summarizes every event correctly."], "A", "The blue backpack is one example, while the broader text concerns organizing a system for many lost items.", "比較選項範圍與全文範圍，避免用一個例子代替主旨。", ["Identify the single example blue backpack.", "Look for the repeated broader subject many items.", "Compare the answer's scope with the text.", "Choose the one-example criticism.", "Rewrite the main idea around the lost-and-found system."]),
]

assert len(DATA) == 10
TARGETS = ["A", "B", "C", "D", "B", "C", "D", "A", "B", "C"]
for i, (prompt, options, answer, explanation, strategy, steps) in enumerate(DATA, 1):
    target = TARGETS[i - 1]
    if target != answer:
        oi, ti = ord(answer) - 65, ord(target) - 65
        correct = options[oi]
        rest = [v for j, v in enumerate(options) if j != oi]
        options = rest[:ti] + [correct] + rest[ti:]
        answer = target
    item = {"id": f"question-english-content-ae-iv-8-{i}", "subject": "english", "type": "single-choice", "prompt": prompt, "options": [{"id": chr(65+j), "text": t} for j, t in enumerate(options)], "knowledgeIds": ["kg-english-content-ae-iv-8"], "difficulty": "medium", "answer": {"value": answer, "explanation": explanation}, "provenance": {"origin": "original", "license": "All rights reserved", "sourceUrl": SOURCES[0][0], "sourceLocator": "公立學校七年級英語段考；只研究故事短文主旨、證據、結局與細節範圍題型。", "authoringNote": "依官方英語文領域課綱、單元 KG 與三個公立學校公開來源，獨立改寫故事短文主旨題；未複製原文、選項、篇章、圖片或答案；待第二輪 AI／Terra 內容複核。"}, "reviewStatus": "draft", "updatedAt": "2026-09-13", "lessonId": LESSON, "examPatternRefs": refs(), "solutionStrategy": strategy, "solutionSteps": steps}
    (OUT / f"question-english-content-ae-iv-8-{i}.json").write_text(json.dumps(item, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
print(f"rewrote {len(DATA)} independent questions for {LESSON}")
